SELECT CASE WHEN unit_price >= 410 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END AS unit_price_bucket, COUNT(*) AS total_count, MIN(quantity) AS min_quantity, AVG(quantity) AS avg_quantity FROM order_items WHERE quantity = 7 AND unit_price > 290 GROUP BY CASE WHEN unit_price >= 410 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END ORDER BY min_quantity DESC, total_count DESC, unit_price_bucket LIMIT 10
